def section(c,head):
 t=(OUT/'evidence/HISTORICAL_SOURCE_ASSESSMENTS'/f'{c}.md').read_text()
 m=re.search(r'## '+re.escape(head)+r'.*?(?=\n## |\Z)',t,re.S)
 return m.group().split('\n',1)[1].strip() if m else ''


def build():
 rows=[];moves={x['code']:x for x in json.loads((OUT/'verification/move_ledger.json').read_text())}
 containers={x['id']:x for x in json.loads((OUT/'verification/container_move_ledger.json').read_text())}
 issue_scope=json.loads((OUT/'verification/issue_code_scope.json').read_text()) if (OUT/'verification/issue_code_scope.json').exists() else {}
 destverify={x['code']:x for x in json.loads((OUT/'verification/destination_payload_checks.json').read_text())} if (OUT/'verification/destination_payload_checks.json').exists() else {}
 copyplan=json.loads((OUT/'verification/copy_plan.json').read_text()) if (OUT/'verification/copy_plan.json').exists() else []
 cp={x['code']:x for x in copyplan if x.get('kind')=='held_original_copy'}
 corr={x['source_code']:x for x in json.loads((OUT/'correction_evidence/CORRECTION_ATTEMPTS.json').read_text())}
 for src in SCOPE:
  c=src['code']
  if c in SPEC:d=SPEC[c].copy()
  elif src['role']=='support record':
   d=dict(route='documents',rationale='Preserve exact submitted documentary/support record as evidence of its author\'s claims, chronology and provenance, not independent proof or new artwork authority.',permitted_use='Documentary evidence only; source-specific research/assessment errata apply without original edits.',direction='Retain filename, ID and payload. Annotate by final cross-reference only; do not rerun reported historical actions.',required_role='No external authority needed for documentary retention.',authority_question='None for documentary retention.',missing_input='None for documentary retention.',objective_closure_test='Original exists, opens and matches source size/MD5/SHA256 in documentary destination; any author claims remain attributed.',issues=[])
  elif src['role'] in ['comparison aid','diagnostic aid']:
   d=dict(route='aids',rationale='Comparison/diagnostic artifact is reference evidence, not a new artwork candidate, native geometry authority or operative correction instruction.',permitted_use='Review/reference aid only; embedded version labels/metrics remain historical claims.',direction='Preserve unmodified. Do not substitute compressed comparison panels for exact native artwork or execute withdrawn guides.',required_role='No external authority needed for aid retention.',authority_question='None for aid retention.',missing_input='None for aid retention.',objective_closure_test='Exact bytes/identity retained and source-specific limitations attached.',issues=['G16'] if c in ['E24','E36','E39','E42'] else [])
  elif c in SUCCESSOR:
   d=dict(route='superseded',rationale='Exact earlier generation superseded in version lineage by '+SUCCESSOR[c]+'. Successor existence does not imply approval.',permitted_use='Superseded creative evidence only; no independent release.',direction='Preserve unmodified; follow successor exact verdict rather than promoting this earlier file.',required_role='None for archival retention.',authority_question='None for archival retention.',missing_input='None for archival retention.',objective_closure_test='Exact original retained with traceable successor; successor permission remains separately stated.',issues=['G08'] if c in ['B08','B09','B10'] else [])
  else:raise AssertionError('Undecided original '+c)
  d['issues']=sorted(set(d['issues']) | {issue for issue,codes in issue_scope.items() if c in codes})
  route=d.pop('route');folderkey='visual_release' if route=='release' else route
  dest=F[folderkey]
  if route=='documents' and c!='A01':
   container='original_container' if src['group']=='ORIGINAL' else 'assistant_container'
   # Group names are preserved from canonical source scope; use parent ID as definitive join.
   container='original_container' if src['source_parent_id']==F['original_container']['id'] else 'assistant_container'
   parent=F[container]['id'];path=dest['path']+'/'+F[container]['path'].split('/')[-1]+'/'+src['name'];motion='submission_container_relocation'
  else:parent=dest['id'];path=dest['path']+'/'+src['name'];motion='direct_file_parent_change'
  r={k:src[k] for k in ['code','name','source_id','source_parent_id','source_drive_version','source_size','source_md5','source_sha256','role','currency','research_id','research_drive_version','research_sha256','research_size']}
  r.update(d);r.update(final_verdict=V[route],destination_category=route,destination_root_id=dest['id'],final_parent_id=parent,final_path=path,original_path=('PRODUCTION/PENDING/'+('ORIGINAL_VA_SUBMISSIONS/' if src['source_parent_id']==F['original_container']['id'] else 'ASSISTANT_VA_SUBMISSIONS/' if src['source_parent_id']==F['assistant_container']['id'] else '')+src['name']),movement_type=motion,in_held_36=c in HELD,source_assessment='evidence/HISTORICAL_SOURCE_ASSESSMENTS/'+c+'.md',evidence_finding=section(c,'05.'),historical_research_reconciliation=section(c,'07.'),successor_code=SUCCESSOR.get(c),selected_derivative=NEW.get(c),operation_observation=moves.get(c) or {'inherited_container_relocation':containers.get(parent),'original_file_parent_unchanged':True},destination_verification=destverify.get(c),package_copy=cp.get(c))
  if c in corr:r['correction_result']=corr[c]
  rows.append(r)
 assert len(rows)==193 and len({r['source_id'] for r in rows})==193
 assert sum(r['in_held_36'] for r in rows)==36
 assert all(r['destination_verification'] and r['destination_verification'].get('complete_destination_verified') for r in rows)
 assert len(moves)==106 and sum(r['movement_type']=='submission_container_relocation' for r in rows)==87
 assert all(r['package_copy'] and r['package_copy'].get('complete_copy_verified') for r in rows if r['in_held_36'])
 assert all(r['operation_observation'] for r in rows)
 assert not any('HOLD'==r['final_verdict'] for r in rows)
 (OUT/'A_MASTER_FINAL_VERDICT_REGISTER.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
 cols=['code','name','source_id','role','final_verdict','permitted_use','rationale','direction','required_role','authority_question','missing_input','objective_closure_test','original_path','final_path','final_parent_id','source_drive_version','source_size','source_md5','source_sha256','research_id','research_drive_version','issues','in_held_36','successor_code','selected_derivative']
 with (OUT/'A_MASTER_FINAL_VERDICT_REGISTER.csv').open('w',newline='') as h:
  w=csv.DictWriter(h,fieldnames=cols,extrasaction='ignore');w.writeheader()
  for r in rows:w.writerow({**r,'issues':' '.join(r['issues'])})
 lines=['# A — Master final verdict register','', 'Fixed original denominator: **193**. Exactly one final verdict per original. Derivatives and intentional package copies are extra objects, never extra originals. No row is an indefinite HOLD.','', 'Execution/verification fields in JSON are independently joined, not implied by a verdict. See F/G for actual clearance status.','', '| Code | Original | Final verdict | Permitted use / limitation | Destination |','|---|---|---|---|---|']
 for r in rows:lines.append(f"| {r['code']} | [{r['name']}](https://drive.google.com/file/d/{r['source_id']}/view) | {r['final_verdict']} | {r['permitted_use'].replace('|','/')} | `{r['final_path']}` |")
 (OUT/'A_MASTER_FINAL_VERDICT_REGISTER.md').write_text('\n'.join(lines)+'\n')
 per=OUT/'verdicts';per.mkdir(exist_ok=True)
 for r in rows:
  text=f"# {r['code']} — Final CD verdict\n\n**{r['final_verdict']}**\n\nOriginal: `{r['name']}` · ID `{r['source_id']}`\n\n## Permitted use\n{r['permitted_use']}\n\n{NOT_PROD}\n\n## Decision and rationale\n{r['rationale']}\n\n## Precise direction / non-actions\n{r['direction']}\n\n## Authority / missing-input closure\n- Role: {r['required_role']}\n- Question: {r['authority_question']}\n- Missing: {r['missing_input']}\n- Objective test: {r['objective_closure_test']}\n\n## Exact evidence and reconciliation\nThe following source findings/reconciliation are preserved from the historical full assessment, not a claim of a new semantic/visual review of every source. Current final decision and actual correction/filing evidence are stated separately.\n\nResearch `{r['research_id']}` · SHA256 `{r['research_sha256']}`\n\n{r['evidence_finding']}\n\n{r['historical_research_reconciliation']}\n\n## Traceability\n- Original path: `{r['original_path']}`\n- Final path: `{r['final_path']}`\n- Original/final parent identity: `{r['source_parent_id']}` → `{r['final_parent_id']}`\n- Motion: `{r['movement_type']}`\n- Source bytes: {r['source_size']} · MD5 `{r['source_md5']}` · SHA256 `{r['source_sha256']}`\n- Issues: {' '.join(r['issues']) or 'source-specific role retention'}\n- Successor generation: {r['successor_code'] or 'none'} (not automatic approval).\n- Selected bounded derivative: {r['selected_derivative'] or 'none'}.\n\n## Actual execution evidence\nSuccessful operation observation and independent destination payload/listing verification are in the master JSON and F manifest; absent evidence is not completion. Package copies are intentional, distinct IDs, never moves or extra originals.\n"
  dv=r['destination_verification']
  text+=f"\n## Completed physical verification\n- Exact original ID downloaded after filing: **PASS**.\n- Original byte count, MD5 and SHA256: **PASS / unchanged**.\n- Full raster decode or strict full UTF-8 decode: **PASS** (not new semantic/cultural approval).\n- Complete destination membership reconciliation: **PASS**.\n- Final parent: [{r['final_parent_id']}](https://drive.google.com/drive/folders/{r['final_parent_id']}).\n- Baseline source Drive revision: {r['source_drive_version']}; metadata-only parent moves may advance Drive revision, not the artwork generation.\n- Historical complete assessment (preserved, NOT current authority): [{r['code']}](../{r['source_assessment']}).\n"
  cp=r['package_copy']
  if cp:
   text+=f"\n## Intentional held-cohort package copy\n- Original ID `{cp['source_id']}` → distinct copy ID [{cp['new_id']}](https://drive.google.com/file/d/{cp['new_id']}/view).\n- Name and payload unchanged; copied, independently downloaded by the NEW ID, fully opened and hash/parent verified: **PASS**.\n- Sole package parent: `{cp['destination_id']}`.\n- This is not a second original and does not change this original's verdict.\n"
  if r.get('correction_result'):
   cr=r['correction_result']
   text+=f"\n## Actual derivative attempt / decision\n- Separate output: `{cr['output_name']}` · [{cr['new_drive_id']}](https://drive.google.com/file/d/{cr['new_drive_id']}/view).\n- Actual state: **{cr['completion_state']}**.\n- Source preserved: {cr['original_preserved']}; output upload and independent hash/open verification: {cr['independent_download_verified']}.\n- Output SHA256: `{cr['output_sha256']}`.\n- Exact masks/parameters/visual limits: `correction_evidence/CORRECTION_ATTEMPTS.json` and `D_CORRECTION_AND_REPLACEMENT_RECORD.md`.\n- Failed V003 lighting grades are NOT replacements. Selected derivatives have internal-study permission only.\n"
  (per/f"{r['code']}.md").write_text(text)
 print(json.dumps({'originals':len(rows),'verdict_counts':dict(collections.Counter(r['final_verdict'] for r in rows)),'held36':dict(collections.Counter(r['final_verdict'] for r in rows if r['in_held_36']))},indent=2))
 return rows

